package net.civeira.phylax.feature.observe.observeddashboard.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.feature.observe.observeddashboard.domain.ObservedDashboardSourceKindOptions;

class SourceKindVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property source kind of observed dashboard ")
  void test_source_kind_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> SourceKindVO.tryFrom("_BACKEND_"));
    Assertions.assertEquals(ObservedDashboardSourceKindOptions.BACKEND,
        SourceKindVO.tryFrom("BACKEND").getSourceKind().orElse(null));
    Assertions.assertFalse(SourceKindVO.nullValue().getSourceKind().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(SourceKindVO.tryFrom(null).getSourceKind().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals(ObservedDashboardSourceKindOptions.BACKEND,
        SourceKindVO.from(ObservedDashboardSourceKindOptions.BACKEND).getSourceKind().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> SourceKindVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + ObservedDashboardSourceKindOptions.BACKEND + "]",
        SourceKindVO.from(ObservedDashboardSourceKindOptions.BACKEND).toString());
  }
}
